"""Exact v6 evaluation policy copied from its semantic authority."""
import base64
import hashlib
import json

_BYTES = base64.b64decode('', validate=True)
if len(_BYTES) != 850 or hashlib.sha256(_BYTES).hexdigest().upper() != '1FB9B260CB8CBA831A5F61C44143F5CC98C537B58D64B803700FBEC2FB750754':
    raise ImportError("evaluation policy constant mismatch")
POLICY = json.loads(_BYTES)
